const { test } = require("node:test");
const assert = require("node:assert/strict");
const { startServer, api } = require("./helpers");

async function makeItem(base, quantity) {
  const w = await api(base, "POST", "/api/warehouses", { name: "W", location: "x" });
  const item = await api(base, "POST", "/api/items", {
    sku: "SKU", name: "Widget", warehouseId: w.json.id, quantity, reorderThreshold: 0,
  });
  return item.json.id;
}

test("bulk batch applies fully when every step stays non-negative", async () => {
  const { base, close } = startServer();
  try {
    const itemId = await makeItem(base, 10);
    const r = await api(base, "POST", `/api/items/${itemId}/movements/bulk`, {
      movements: [
        { type: "OUT", quantity: 5 },
        { type: "IN", quantity: 2 },
        { type: "OUT", quantity: 3 },
      ],
    });
    assert.equal(r.status, 201);
    assert.equal(r.json.item.quantity, 4);
    assert.equal(r.json.movements.length, 3);
  } finally {
    await close();
  }
});

test("bulk batch that goes negative partway through is rejected in full - no partial commit", async () => {
  const { base, close } = startServer();
  try {
    const itemId = await makeItem(base, 10);
    const r = await api(base, "POST", `/api/items/${itemId}/movements/bulk`, {
      movements: [
        { type: "OUT", quantity: 5 },
        { type: "OUT", quantity: 4 },
        { type: "OUT", quantity: 5 },
      ],
    });
    assert.equal(r.status, 400);

    const item = await api(base, "GET", `/api/items/${itemId}`);
    assert.equal(item.json.quantity, 10, "quantity must be UNCHANGED - the first two movements must not have been committed");

    const movements = await api(base, "GET", `/api/items/${itemId}/movements`);
    assert.equal(movements.json.length, 0, "no movements from the rejected batch may be recorded");
  } finally {
    await close();
  }
});

