const itemStore = require("../store/itemStore");
const movementStore = require("../store/movementStore");

const VALID_TYPES = new Set(["IN", "OUT"]);

function validateOne({ type, quantity }) {
  if (!VALID_TYPES.has(type)) {
    return "type must be IN or OUT";
  }
  if (typeof quantity !== "number" || !Number.isInteger(quantity) || quantity <= 0) {
    return "quantity must be a positive integer";
  }
  return null;
}

/**
 * Applies a stock movement to an item: IN adds to quantity, OUT subtracts.
 * Returns { error } on validation failure, or { movement, item } on success.
 * Rejects an OUT movement that would take quantity below zero.
 */
function applyMovement(item, { type, quantity, note }) {
  const err = validateOne({ type, quantity });
  if (err) return { error: err };

  const delta = type === "IN" ? quantity : -quantity;
  const newQuantity = item.quantity + delta;
  if (newQuantity < 0) {
    return { error: "movement would take quantity below zero" };
  }

  itemStore.updateItem(item.id, { quantity: newQuantity });
  const movement = movementStore.createMovement({
    itemId: item.id,
    type,
    quantity,
    note: typeof note === "string" ? note : null,
    at: new Date().toISOString(),
  });
  return { movement, item: itemStore.getItem(item.id) };
}

/**
 * Applies a batch of movements atomically: validates every entry AND
 * simulates the running quantity across the whole batch first. If any
 * entry is invalid, or the simulated quantity would ever go negative,
 * NOTHING in the batch is applied - only after the whole batch is proven
 * safe do we actually mutate the store.
 */
function applyBulkMovements(item, movements) {
  if (!Array.isArray(movements) || movements.length === 0) {
    return { error: "movements must be a non-empty array" };
  }

  let simulated = item.quantity;
  for (const m of movements) {
    const err = validateOne(m);
    if (err) return { error: err };
    const delta = m.type === "IN" ? m.quantity : -m.quantity;
    simulated += delta;
    if (simulated < 0) {
      return { error: "batch would take quantity below zero" };
    }
  }

  const applied = [];
  for (const m of movements) {
    const result = applyMovement(itemStore.getItem(item.id), m);
    applied.push(result.movement);
  }
  return { movements: applied, item: itemStore.getItem(item.id) };
}

module.exports = { applyMovement, applyBulkMovements };

